import{c as t,Q as a,j as o,m as n}from"./chunks/framework.BqPkuuVc.js";const p=JSON.parse('{"title":"Importing event data","description":"","frontmatter":{},"headers":[],"relativePath":"user/event-setup/import-event-data.md","filePath":"user/event-setup/import-event-data.md"}'),r={name:"user/event-setup/import-event-data.md"};function s(i,e,l,h,d,c){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="importing-event-data" tabindex="-1">Importing event data <a class="header-anchor" href="#importing-event-data" aria-label="Permalink to &quot;Importing event data&quot;">​</a></h1><p>How to populate classes, courses, controls, and competitors by importing from IOF XML files, Purple Pen, or Eventor — so you don&#39;t have to enter everything by hand.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Manager supports four ways to bring data in:</p><table tabindex="0"><thead><tr><th>Method</th><th>What it gives you</th><th>When to use</th></tr></thead><tbody><tr><td><strong>IOF XML files</strong> (<code>.xml</code>)</td><td>Courses, controls, classes, competitors, clubs, start times</td><td>You have export files from your course setter (IOF CourseData) or entry system (IOF EntryList, ClassList, StartList). Manager parses the IOF v3 schema.</td></tr><tr><td><strong>Purple Pen file</strong> (<code>.ppen</code>)</td><td>Courses and controls</td><td>Your course setter uses Purple Pen and you have the <code>.ppen</code> file.</td></tr><tr><td><strong>Eventor</strong></td><td>Classes, competitors, clubs, start times</td><td>Your federation uses Eventor for entries and you&#39;ve configured the connection in Settings.</td></tr><tr><td><strong>Ranking list</strong> (<code>.xml</code>, <code>.json</code>, <code>.csv</code>)</td><td>Rankings, applied to competitors the event already has</td><td>You&#39;ve been handed a ranking list and want to seed the <a href="./start-draw#drawing-by-ranking">start draw</a> with it. See <a href="#importing-rankings">Importing rankings</a>.</td></tr></tbody></table><p>These are not mutually exclusive — you can import courses from Purple Pen and competitors from Eventor for the same event, for example.</p><h2 id="where-to-import" tabindex="-1">Where to import <a class="header-anchor" href="#where-to-import" aria-label="Permalink to &quot;Where to import&quot;">​</a></h2><p>Open the event dashboard and click <strong>Import</strong>. The <strong>Import Data</strong> dialog has three tabs:</p><ul><li><strong>Local Files</strong> — browse and upload IOF XML or Purple Pen files.</li><li><strong>Linked Event</strong> — re-import data from an Eventor event that&#39;s already linked to this event (useful for picking up late entries).</li><li><strong>Other Event</strong> — search for any Eventor event and import from it, with the option to link it for future re-imports.</li></ul><h2 id="importing-iof-xml-files" tabindex="-1">Importing IOF XML files <a class="header-anchor" href="#importing-iof-xml-files" aria-label="Permalink to &quot;Importing IOF XML files&quot;">​</a></h2><h3 id="course-data-iof-coursedata-xml" tabindex="-1">Course data (IOF CourseData XML) <a class="header-anchor" href="#course-data-iof-coursedata-xml" aria-label="Permalink to &quot;Course data (IOF CourseData XML)&quot;">​</a></h3><p>Upload a file containing course and control definitions — the output of your course-setting software (e.g. OCAD, Condes, Purple Pen).</p><p>What gets created:</p><ul><li><strong>Controls</strong> — one for each control referenced by a course. Normal controls keep their punch code; Start, Finish and Check controls are imported as named map positions (e.g. &quot;Start 1&quot;) with no code of their own — radio routing for those types comes from the event&#39;s start/finish/check unit-code lists.</li><li><strong>Courses</strong> — each course with its ordered chain (Start → middle controls → Finish). Each course&#39;s Start and Finish are recorded individually, so a multi-Start map imports as two courses anchored at different Start controls.</li><li><strong>Class course assignments</strong> — if the file contains <code>ClassCourseAssignment</code> entries (most course setters export them, e.g. Purple Pen and OCAD), each named class gets its <a href="./classes-and-courses#assigning-courses-to-classes">course pool</a> set to the named course(s) — no manual assigning needed, even when the course names don&#39;t match the class names. The file is authoritative for the classes it names (their pools are replaced); classes it doesn&#39;t name are untouched. An assignment is skipped — and reported in the import summary — when the class name doesn&#39;t match any class in the event or the course name isn&#39;t recognised. Classes are matched by name, so import classes <strong>before</strong> the course file if you want these assignments applied; with no classes in the event yet, the assignments are simply skipped.</li><li><strong>Per-competitor course locks</strong> — if the file contains <code>PersonCourseAssignment</code> or (for relays) <code>TeamMemberCourseAssignment</code> entries, each one locks the named competitor to the named course (see <a href="./classes-and-courses#course-pools-and-locking-a-competitor-to-a-course">Locking a competitor to a course</a>). Competitors are matched by their Eventor/IOF person ID, then by bib number. An assignment is skipped — and reported in the import summary — when the competitor can&#39;t be matched, the course name isn&#39;t recognised, or the course isn&#39;t in that competitor&#39;s class course pool. So import competitors (and, for relays, their bibs via the start list) <strong>before</strong> the course file if you want these locks applied.</li></ul><p>After a course import, the <a href="./classes-and-courses#assigning-courses-to-classes">Assign Courses to Classes dialog</a> opens automatically — but only if at least one class is still without a course. If the file&#39;s class course assignments covered every class, there&#39;s nothing left to do and the dialog stays closed.</p><blockquote><p><strong>Tip:</strong> If a control code in the file already exists in the event, it&#39;s matched and updated rather than duplicated.</p></blockquote><h4 id="from-condes-or-ocad" tabindex="-1">From Condes or OCAD <a class="header-anchor" href="#from-condes-or-ocad" aria-label="Permalink to &quot;From Condes or OCAD&quot;">​</a></h4><p>If the courses were created in Condes or OCAD, then use the standard <strong>IOF CourseData XML</strong>.</p><p><strong>Condes:</strong> open your event, then <strong>File → Export → Export course data as XML…</strong>. Choose <strong>IOF Version 3.0</strong> and <strong>UTF-8</strong> encoding (both recommended), and export. Upload the resulting <code>.xml</code> here.</p><p><strong>OCAD:</strong> use <strong>Course Setting → Export → Course Data (XML)…</strong> and choose the IOF XML v3 format. Upload the resulting <code>.xml</code> here.</p><blockquote><p><strong>Note on coordinates:</strong> Condes and OCAD write control positions as millimetres on the printed map, not as real-world latitude/longitude. That&#39;s expected — Manager uses the map-relative positions and leg lengths from the file. (For multi-map events, Condes exports controls for one chosen canvas/map at a time, so export from the map whose control positions you want.)</p></blockquote><h3 id="class-list-iof-classlist-xml" tabindex="-1">Class list (IOF ClassList XML) <a class="header-anchor" href="#class-list-iof-classlist-xml" aria-label="Permalink to &quot;Class list (IOF ClassList XML)&quot;">​</a></h3><p>Upload a file defining classes.</p><p>What gets created:</p><ul><li><strong>Classes</strong> — one for each class defined in the file.</li></ul><h3 id="entry-list-iof-entrylist-xml" tabindex="-1">Entry list (IOF EntryList XML) <a class="header-anchor" href="#entry-list-iof-entrylist-xml" aria-label="Permalink to &quot;Entry list (IOF EntryList XML)&quot;">​</a></h3><p>Upload a file of competitor entries — typically exported from your entry system.</p><p>What gets created:</p><ul><li><strong>Competitors</strong> — one for each entry, with name, card number, and class assignment.</li><li><strong>Clubs</strong> — any clubs referenced by competitors that don&#39;t already exist.</li><li><strong>Classes</strong> — any classes referenced by competitors that don&#39;t already exist.</li></ul><h4 id="rankings-in-an-entry-list" tabindex="-1">Rankings in an entry list <a class="header-anchor" href="#rankings-in-an-entry-list" aria-label="Permalink to &quot;Rankings in an entry list&quot;">​</a></h4><p>Most entry lists carry no <a href="./competitors-clubs-teams#ranking">ranking</a> at all — there is no ranking field in the IOF XML standard. The nearest thing it has is a <code>&lt;Score&gt;</code>, and what a score <em>means</em> is whatever its <code>type</code> says: World Ranking points, a series total, anything.</p><p>So Manager reads a score as a ranking <strong>only when its type says it is a rank</strong> (<code>Rank</code> or <code>Ranking</code>), and leaves every other kind of score alone. That is not caution for its own sake: World Ranking points run the other way — bigger is better — so a points value read as a place would seed your whole field backwards and nothing on screen would say so.</p><p>You aren&#39;t left guessing, though. If the file carried scores Manager wouldn&#39;t read, the import summary says so once per kind, naming the type and how many entries had one — so a file that <em>did</em> carry something doesn&#39;t just appear to have lost it. Scores with no type at all are counted the same way, in a note of their own, since there is no name to give them. And a value labelled as a rank but not actually a place (a decimal, a negative, a zero) is reported as a warning; that entry keeps whatever ranking it already had.</p><p>An Orienteering JSON entry list or start list carries rankings properly, with no labelling to get right — Manager writes them into the files it exports, too, in both formats. See <a href="./competitors-clubs-teams#exporting-the-entry-list">Exporting the entry list</a>.</p><p>If what you have is a ranking list rather than an entry list — a spreadsheet, or a federation&#39;s published file — import it separately: see <a href="#importing-rankings">Importing rankings</a>.</p><h3 id="start-list-iof-startlist-xml" tabindex="-1">Start list (IOF StartList XML) <a class="header-anchor" href="#start-list-iof-startlist-xml" aria-label="Permalink to &quot;Start list (IOF StartList XML)&quot;">​</a></h3><p>Upload a file of allocated start times — typically exported from an entry system or start-list draw tool.</p><p>What it does:</p><ul><li>Matches competitors by <strong>person ID</strong>, then <strong>card</strong>, then <strong>name</strong>, and sets their allocated start times.</li><li>Captures each competitor&#39;s <strong>bib number</strong> from the file, so a later course-data import can match per-competitor course assignments by bib (important for relays).</li><li>Skips competitors who have already punched (so a late re-import can&#39;t overwrite a result).</li><li>Does <strong>not</strong> create new competitors — only updates existing ones.</li></ul><h3 id="re-importing" tabindex="-1">Re-importing <a class="header-anchor" href="#re-importing" aria-label="Permalink to &quot;Re-importing&quot;">​</a></h3><p>You can re-import the same file (or an updated version) at any point while setting up. Manager matches existing items by their identifiers (control code for controls, name for classes/competitors, etc.) and updates them rather than creating duplicates.</p><h3 id="when-a-file-is-missing-competitors-or-classes-you-already-have" tabindex="-1">When a file is missing competitors or classes you already have <a class="header-anchor" href="#when-a-file-is-missing-competitors-or-classes-you-already-have" aria-label="Permalink to &quot;When a file is missing competitors or classes you already have&quot;">​</a></h3><p>Only you know whether an entry list is the <strong>complete</strong> list of everyone entered, or a <strong>partial</strong> one to add on top of what&#39;s already in the event — runners you added by hand, imported from a CSV, or who turned up and entered on the day. So when a file omits competitors (or classes) the event already has, Manager stops and asks. Nothing is written until you answer.</p><p>You get a list of exactly who (or what) is missing from the file — competitors that already have downloaded race data are flagged — and three choices:</p><ul><li><strong>Delete these competitors / classes</strong> — the file is the complete list, so anyone missing from it is removed, along with any results they have.</li><li><strong>Keep them and import</strong> — the file is a partial list. Everything in it is added or updated, and anyone missing from it is left exactly as they are. Nothing is deleted.</li><li><strong>Cancel</strong> — nothing at all happens; the event is untouched.</li></ul><p>An import that only adds and updates never asks — it just runs.</p><p>Course files never delete courses — courses absent from the file are always left in place.</p><h3 id="when-a-file-brings-the-event-s-own-start-settings" tabindex="-1">When a file brings the event&#39;s own start settings <a class="header-anchor" href="#when-a-file-brings-the-event-s-own-start-settings" aria-label="Permalink to &quot;When a file brings the event&#39;s own start settings&quot;">​</a></h3><p>An Orienteering JSON file describes the event it came from, including its <strong>mass start</strong>, its <strong>restart</strong> and whether a <strong>punched start overrides the allocated start</strong>. Those three decide how every competitor&#39;s start time is worked out, so Manager never takes them quietly. If the file&#39;s differ from this event&#39;s, importing entries or start times stops and shows you both sides — this event&#39;s setting and the file&#39;s — before anything is written:</p><ul><li><strong>Apply start settings</strong> — this event takes the file&#39;s mass start, restart and punching-start setting, and then the import runs.</li><li><strong>Import without them</strong> — the entries and their times still arrive, and the event keeps its own settings. A time the file&#39;s settings produced is then stored on each competitor individually, so if you move this event&#39;s mass start afterwards those runners stay behind at the old time.</li><li><strong>Cancel</strong> — nothing at all happens; the event is untouched.</li></ul><p>A file stating the settings this event already uses never asks, so re-importing costs you nothing.</p><h3 id="when-a-file-brings-courses-scored-in-any-order" tabindex="-1">When a file brings courses scored in any order <a class="header-anchor" href="#when-a-file-brings-courses-scored-in-any-order" aria-label="Permalink to &quot;When a file brings courses scored in any order&quot;">​</a></h3><p>An Orienteering JSON file says how each course is <strong>scored</strong> — in the printed order, as a scatter course (a set number of controls, any order), or as a score course. Importing one brings that with it, along with how many controls a scatter course requires, so the courses score the same way in this event as they did in the event the file came from.</p><p>One thing to expect on the <strong>Courses</strong> page afterwards: a scatter or score course arrives with <strong>no control sequence</strong>. That is not a failed import. Those courses are run against every control in the event, so a sequence is not what they are scored on and the file does not carry one — listing the controls in play as though they were an order to visit them in would be inventing one. If you later switch such a course back to a line course, import the course file (IOF XML or Purple Pen) to give it its printed sequence.</p><h2 id="importing-rankings" tabindex="-1">Importing rankings <a class="header-anchor" href="#importing-rankings" aria-label="Permalink to &quot;Importing rankings&quot;">​</a></h2><p>A <a href="./competitors-clubs-teams#ranking">ranking</a> is a competitor&#39;s place on an external ranking list — 1 being the best-ranked athlete. Ranking lists are published separately from entries and republished every few weeks, so they are imported separately: <strong>Rankings</strong> is its own box at the bottom of the <strong>Local Files</strong> tab.</p><p>This import <strong>only ever fills in the Ranking field of competitors the event already has.</strong> It creates nobody, deletes nobody, and changes nothing else. Import your entries first.</p><h3 id="which-files-manager-accepts" tabindex="-1">Which files Manager accepts <a class="header-anchor" href="#which-files-manager-accepts" aria-label="Permalink to &quot;Which files Manager accepts&quot;">​</a></h3><p>Three kinds, and the only thing that differs between them is how much you have to say about the file:</p><table tabindex="0"><thead><tr><th>File</th><th>What Manager reads</th><th>What you have to do</th></tr></thead><tbody><tr><td><strong>IOF XML</strong> (<code>.xml</code>)</td><td>A competitor list, or an entry list, in which an athlete carries a score labelled as a rank</td><td>Nothing — choose the file and import it</td></tr><tr><td><strong>Orienteering JSON</strong> (<code>.json</code>)</td><td>Any Orienteering JSON document that lists entries: an entry list, a start list, or a result list</td><td>Nothing — choose the file and import it</td></tr><tr><td><strong>CSV</strong> (<code>.csv</code>)</td><td>A spreadsheet of places, in whatever columns your list happens to use</td><td>Say which column is which, in the dialog that opens</td></tr></tbody></table><p>An IOF XML or Orienteering JSON file <strong>says what each number in it is</strong>, so Manager reads it as it stands: choose the file, click the upload arrow, and it imports in one step. A spreadsheet says nothing about itself — one list&#39;s third column is a place, another&#39;s is a points total — so a CSV always goes through the column-mapping dialog first. That is the whole of the difference; everything after the file is read is the same for all three.</p><blockquote><p><strong>Note:</strong> If your ranking list is an <code>.xlsx</code> (or anything else a spreadsheet program opens), use <strong>Save as</strong> / <strong>Export</strong> to write a <code>.csv</code> first.</p></blockquote><h3 id="which-iof-xml-files-carry-a-ranking" tabindex="-1">Which IOF XML files carry a ranking <a class="header-anchor" href="#which-iof-xml-files-carry-a-ranking" aria-label="Permalink to &quot;Which IOF XML files carry a ranking&quot;">​</a></h3><p>IOF XML has no ranking field. The nearest thing it has is a <code>&lt;Score&gt;</code>, and what a score <em>means</em> is whatever its <code>type</code> says — so Manager reads a score as a ranking only where the file lists <strong>people</strong> and the score is labelled as a <strong>rank</strong> (<code>Rank</code> or <code>Ranking</code>). Two documents qualify:</p><ul><li><strong>A competitor list</strong> — a list of athletes and the scores they hold. This is the shape a federation ranking list is usually published in.</li><li><strong>An entry list</strong> — the entries for an event. A relay&#39;s leg runners count too: a runner on leg 2 carries a ranking exactly as an individual entrant does.</li></ul><p><strong>A results file does not work</strong>, and Manager tells you rather than importing something wrong. The scores in a results file are what someone scored on the day — World Ranking points, most often — and points run the <em>opposite</em> way to a place: bigger is better. Read as places, 1250 points would become &quot;1250th&quot;, and your whole field would be seeded backwards with nothing on screen to say so. So Manager reads the file, declines it, and reports:</p><blockquote><p>No rankings were read: the scores in a results file are points rather than places on a ranking list. Import a competitor list or an entry list instead.</p></blockquote><p>Any other IOF document — a start list, a class list, a course file — is turned away outright, with <em>&quot;Check that the file is a ranking list&quot;</em>: there is nowhere in those for a ranking to be.</p><p>The same care applies inside a file that <em>does</em> work. A score of any other type — or with no type at all — is left alone, and the import summary says so once per kind, naming the type and how many entries carried one. A file that did carry something never just appears to have lost it.</p><h3 id="what-an-orienteering-json-file-needs" tabindex="-1">What an Orienteering JSON file needs <a class="header-anchor" href="#what-an-orienteering-json-file-needs" aria-label="Permalink to &quot;What an Orienteering JSON file needs&quot;">​</a></h3><p>Nothing in particular. A ranking travels on the entry itself in Orienteering JSON, so any document that lists entries is already a ranking list: an entry list, a start list, or a result list all work, and there is no separate ranking-list file to produce. Last season&#39;s result list, exported from Manager, seeds this season&#39;s draw exactly as it stands.</p><h3 id="importing-rankings-from-a-csv" tabindex="-1">Importing rankings from a CSV <a class="header-anchor" href="#importing-rankings-from-a-csv" aria-label="Permalink to &quot;Importing rankings from a CSV&quot;">​</a></h3><p>A spreadsheet is the way a ranking list most often arrives, and the only one of the three that needs anything from you before it can be read.</p><h4 id="what-the-file-needs" tabindex="-1">What the file needs <a class="header-anchor" href="#what-the-file-needs" aria-label="Permalink to &quot;What the file needs&quot;">​</a></h4><p>Two things, in whatever columns and whatever order your list happens to use:</p><ol><li><strong>The ranking</strong> — a whole number. 1 is best.</li><li><strong>Something that says whose ranking it is</strong> — any one of an <strong>IOF ID</strong>, a <strong>competitor ID</strong> (the organiser&#39;s own entry number), a <strong>card number</strong>, or a <strong>name</strong>. A name can be one full-name column or separate given-name and family-name columns.</li></ol><p>Extra columns — club, class, region, points, anything — are ignored. You don&#39;t need to tidy the file up first.</p><h4 id="mapping-the-columns" tabindex="-1">Mapping the columns <a class="header-anchor" href="#mapping-the-columns" aria-label="Permalink to &quot;Mapping the columns&quot;">​</a></h4><p>Choose the file and click the upload arrow, and the <strong>Import rankings from CSV</strong> dialog opens. Manager reads the file, guesses how it&#39;s put together, and shows you what it found so you can correct it:</p><ul><li><strong>Delimiter</strong> — semicolon, comma or tab. Manager detects it; change it here if the preview looks wrong (all of one row crammed into a single column is the usual symptom).</li><li><strong>First row is a header</strong> — on when Manager recognised the first row as column headings. If your file has no headings, switch it off and every row is treated as data.</li><li><strong>A drop-down per field</strong> — <strong>Ranking (place)</strong>, <strong>IOF ID</strong>, <strong>Competitor ID</strong>, <strong>Card / chip no.</strong>, <strong>Full name</strong>, <strong>Given name</strong>, <strong>Family name</strong>. Manager pre-fills the ones it recognised from the headings; set any it missed, or <strong>(not mapped)</strong> for a column you don&#39;t want used. With no headings to go on it guesses that the first column is the place and the second is the name, and tells you it guessed.</li><li><strong>Preview</strong> — the first few rows of the file as Manager reads them, so you can check the mapping against real data before committing.</li></ul><p>The <strong>Import</strong> button stays disabled until you&#39;ve mapped the ranking column <em>and</em> at least one way of identifying the athlete; the dialog says so while that&#39;s outstanding.</p><h3 id="how-rows-are-matched-to-competitors" tabindex="-1">How rows are matched to competitors <a class="header-anchor" href="#how-rows-are-matched-to-competitors" aria-label="Permalink to &quot;How rows are matched to competitors&quot;">​</a></h3><p>Manager works down the strongest identifier it has, per row: <strong>IOF ID</strong>, then <strong>competitor ID</strong>, then <strong>card number</strong>, then <strong>name</strong>. Names are compared with accents and capitalisation ignored, so <code>asa lindstrom</code> finds <em>Åsa Lindström</em>.</p><p>Two consequences worth knowing:</p><ul><li><strong>One row seeds every entry that person holds.</strong> Someone entered in two classes is two competitors in the event, and both get the ranking — ranking only one of them would leave the other unseeded in a draw you believed was seeded.</li><li><strong>Two rows about the same person both apply</strong>, in file order, so the last one wins.</li></ul><h3 id="what-happens-to-rows-that-don-t-land" tabindex="-1">What happens to rows that don&#39;t land <a class="header-anchor" href="#what-happens-to-rows-that-don-t-land" aria-label="Permalink to &quot;What happens to rows that don&#39;t land&quot;">​</a></h3><p>Nothing is written for them, the rest of the file still imports, and you&#39;re told which rows and why. After the import, the summary reports <strong>Rankings: <em>n</em> updated</strong>, and lists any rows that reached nobody — the first ten, with the name and ranking the file gave and one of two reasons:</p><ul><li><strong>not entered in this event</strong> — nobody in the event matched. Expect a lot of these if you imported a national list: most of the country isn&#39;t at your event. But <em>every</em> row failing usually means the file identifies athletes some other way than your entries do — a mis-mapped identity column, most often — and Manager says so separately when nothing at all matched.</li><li><strong>more than one competitor has that name</strong> — the row landed on two different people and nothing in it says which. Usually that&#39;s a row whose only usable identifier was a name two entrants share; it also happens when a row&#39;s card number or competitor ID is held by two people (a shared hire card, a reused organiser number) and the row&#39;s name doesn&#39;t settle it either. Manager won&#39;t guess. Give that competitor an IOF ID or competitor ID that matches the file, or set their ranking by hand.</li></ul><p>Each is named by where it sits in the file: the line number in a CSV, or the athlete&#39;s position in the document for an IOF XML or Orienteering JSON file — so you can go and look at it either way.</p><p>Individual rows can also be skipped:</p><ul><li>A row that states a ranking but <strong>nothing to say whose it is</strong> — no ID, no card, no name — is skipped, in all three formats.</li><li>A <strong>negative</strong> ranking is never stored, in any format. In a CSV the row is refused and the reason given; in an IOF XML or Orienteering JSON file it&#39;s counted in a notice of its own. Either way that competitor keeps the ranking they already had.</li><li>In an <strong>IOF XML</strong> file, a score labelled as a rank but not actually a place — a decimal, or a zero — is treated the same way: reported, and the entry left as it was. (A zero <em>does</em> mean something in the other two formats — see <a href="#clearing-a-ranking">Clearing a ranking</a>.)</li><li>In a <strong>CSV</strong>, a ranking that <strong>isn&#39;t a number</strong> skips that row, and a <strong>blank</strong> ranking cell is passed over in silence. A published list often names everyone and leaves the unranked blank, and an import never clears a ranking a file says nothing about.</li></ul><h3 id="clearing-a-ranking" tabindex="-1">Clearing a ranking <a class="header-anchor" href="#clearing-a-ranking" aria-label="Permalink to &quot;Clearing a ranking&quot;">​</a></h3><p>Setting a ranking works the same in all three formats. Clearing one does not, and it&#39;s the one asymmetry worth knowing about:</p><ul><li><strong>A CSV or an Orienteering JSON file can clear a ranking</strong>, by stating <code>0</code>. Zero is how Manager writes &quot;not ranked&quot;, so a <code>0</code> in the ranking column is read as an instruction: that competitor&#39;s stored place is removed.</li><li><strong>An IOF XML file cannot.</strong> There is no way to write &quot;not ranked&quot; in IOF XML — an unranked athlete simply has no <code>&lt;Score&gt;</code>, which says nothing rather than saying zero, and a file that says nothing never overwrites what you already have. So an IOF XML import only ever <em>sets</em> a ranking or leaves it alone.</li></ul><p>If you need to clear rankings from an IOF XML list, clear them on the competitors themselves (the <strong>Ranking</strong> field on the <strong>Details</strong> tab, emptied) or import a CSV with <code>0</code> in the ranking column.</p><p>That aside, the rule across every import in Manager is the same: <strong>a file that says nothing about a ranking leaves the stored one alone.</strong> Re-importing an entry list or a start list can&#39;t quietly wipe the rankings you&#39;ve already set.</p><h3 id="re-importing-1" tabindex="-1">Re-importing <a class="header-anchor" href="#re-importing-1" aria-label="Permalink to &quot;Re-importing&quot;">​</a></h3><p>Run it again whenever a new list is published. A competitor who already holds the ranking the file would give them is left untouched, so re-importing the same file changes nothing at all — and the summary shows no <strong>Rankings</strong> line, because nothing was updated.</p><h2 id="importing-from-purple-pen" tabindex="-1">Importing from Purple Pen <a class="header-anchor" href="#importing-from-purple-pen" aria-label="Permalink to &quot;Importing from Purple Pen&quot;">​</a></h2><p>Purple Pen <code>.ppen</code> files are handled the same way as IOF CourseData XML. Upload the <code>.ppen</code> file via the <strong>Import Data</strong> dialog → <strong>Local Files</strong> tab.</p><p>What gets created:</p><ul><li><strong>Controls</strong> — extracted from the Purple Pen event definition, including any Start, Finish and Check controls as named map positions.</li><li><strong>Courses</strong> — each course with its full chain (Start → middle controls → Finish). Per-course Start and Finish anchors are preserved, so a <code>.ppen</code> with multiple Starts imports cleanly.</li></ul><blockquote><p><strong>Note:</strong> Purple Pen provides courses and controls only. You still need to import (or create) classes, competitors, and start times separately.</p></blockquote><h2 id="importing-from-eventor" tabindex="-1">Importing from Eventor <a class="header-anchor" href="#importing-from-eventor" aria-label="Permalink to &quot;Importing from Eventor&quot;">​</a></h2><p>Eventor integration lets you pull entry data directly from your federation&#39;s system without handling files.</p><h3 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h3><p>Before you can import from Eventor, configure the connection in <strong>Settings → Eventor</strong>:</p><ul><li><strong>Host Name</strong> — the URL of your Eventor instance.</li><li><strong>API Key</strong> — your Eventor API credentials.</li><li><strong>Organisation ID</strong> — your club or federation&#39;s Eventor organisation ID.</li></ul><p>If Eventor is not configured, Manager will tell you when you try to import and point you to Settings.</p><h3 id="creating-an-event-from-eventor" tabindex="-1">Creating an event from Eventor <a class="header-anchor" href="#creating-an-event-from-eventor" aria-label="Permalink to &quot;Creating an event from Eventor&quot;">​</a></h3><p>If you don&#39;t have an event yet, the fastest path is <strong>New from Eventor</strong> on the <strong>Events</strong> page — it creates the event and pulls in classes, competitors, clubs, and start times in one step. See <a href="./create-event-from-eventor">Creating an event from Eventor</a> for the full walkthrough.</p><h3 id="importing-into-an-existing-event" tabindex="-1">Importing into an existing event <a class="header-anchor" href="#importing-into-an-existing-event" aria-label="Permalink to &quot;Importing into an existing event&quot;">​</a></h3><p>If you&#39;ve already created an event and want to pull Eventor data into it:</p><ol><li>Open the <strong>Import Data</strong> dialog (available from the Dashboard, Courses, Classes, Competitors, and Teams pages)</li><li>Use the <strong>Other Event</strong> tab to search for the Eventor event.</li><li>Select it, optionally tick <strong>Link this event</strong> so you can re-import later with one click.</li><li>Click <strong>Import</strong>.</li></ol><h3 id="re-importing-from-eventor" tabindex="-1">Re-importing from Eventor <a class="header-anchor" href="#re-importing-from-eventor" aria-label="Permalink to &quot;Re-importing from Eventor&quot;">​</a></h3><p>As entries close and start lists are published, you&#39;ll want to pick up the latest data. If the event is linked to an Eventor event:</p><ol><li>Open the <strong>Import Data</strong> dialog.</li><li>Go to the <strong>Linked Event</strong> tab.</li><li>Click <strong>Re-import</strong>.</li></ol><p>Manager will fetch the latest entries and start times, matching them against the competitors already in the event. New entries are added; updated entries are refreshed.</p><h3 id="multi-race-eventor-events" tabindex="-1">Multi-race Eventor events <a class="header-anchor" href="#multi-race-eventor-events" aria-label="Permalink to &quot;Multi-race Eventor events&quot;">​</a></h3><p>Some Eventor events contain several races — a 3 Days, a two-race weekend. Importing one of those into a single event captures only the first race. Import it as a carnival instead: choose <strong>Multi-stage</strong> in the New Event dialog, then <strong>Import from Eventor</strong>. Manager creates the container and imports <strong>one meshO event per Eventor race</strong>, with the entries split by race and each event attached as a stage. See <a href="./multi-stage-events#from-eventor">Multi-stage events</a>.</p><blockquote><p><strong>Note:</strong> An IOF XML file can also carry several races (its <code>raceNumber</code> tags). Manager reads them, but the file-upload wizard doesn&#39;t yet offer the multi-stage step — import each race&#39;s file into its own stage event for now.</p></blockquote><h2 id="what-to-check-after-import" tabindex="-1">What to check after import <a class="header-anchor" href="#what-to-check-after-import" aria-label="Permalink to &quot;What to check after import&quot;">​</a></h2><p>After any import, it&#39;s worth spending a few minutes verifying the data:</p><ul><li>[ ] Open the <strong>Classes</strong> page — confirm the right classes exist and each has a course assigned.</li><li>[ ] Open the <strong>Courses</strong> page — confirm courses have the right controls in the right order.</li><li>[ ] Open the <strong>Competitors</strong> page — confirm competitors have names, classes, and card numbers. Sort by card number to spot blanks.</li><li>[ ] If start times were imported, check the <strong>Competitors</strong> page — the <strong>Start time</strong> column shows the allocated time and its source.</li><li>[ ] If rankings were imported, turn on the <strong>Ranking</strong> column on the <strong>Competitors</strong> page and sort by it — the people you expect to be seeded should be at the top, and anyone who should have been ranked but isn&#39;t will be sitting with the blanks.</li></ul><blockquote><p><strong>Tip:</strong> If something looks wrong, you can re-import a corrected file — Manager will update rather than duplicate.</p></blockquote><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./create-event">Creating an event</a> — where the event details live</li><li><a href="./classes-and-courses">Classes and courses</a> — editing what the import created</li><li><a href="./controls-and-radio-controls">Controls and radio controls</a> — marking imported controls as radios</li><li><a href="./competitors-clubs-teams">Competitors, clubs and teams</a> — editing imported competitors, and <a href="./competitors-clubs-teams#exporting-the-entry-list">exporting the entry list</a> back out again</li><li><a href="./start-times">Start times</a> — understanding how imported start times interact with other sources</li><li><a href="./start-draw">Drawing start times</a> — seeding a draw with the rankings you imported</li><li><a href="./multi-stage-events">Multi-stage events</a> — importing a multi-race Eventor event as a carnival</li><li><a href="./../advanced/orienteering-json">Orienteering JSON (OJSON)</a> — the format spelled out, for anyone writing the files rather than choosing them</li></ul>',127)])])}const m=t(r,[["render",s]]);export{p as __pageData,m as default};
